INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('김**', 1, 5, '명절에 입히려고 샀는데 너무 귀여워요! 우리 강아지가 한복 입으니까 진짜 왕자님 같아요.', '2024-12-01T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('박**', 1, 5, '품질 좋고 디자인도 예쁘네요. 설날에 또 주문할게요!', '2024-11-28T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('이**', 1, 4, '생각보다 사이즈가 작아서 한 치수 크게 주문하는 걸 추천해요.', '2024-11-25T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('최**', 1, 5, '배송 빠르고 상품도 만족스러워요. 가족들한테 자랑 많이 했어요 ㅎㅎ', '2024-11-20T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('정**', 1, 5, '한복 색감이 정말 예뻐요. 사진보다 실물이 더 좋아요!', '2024-11-15T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('강**', 1, 4, '재질이 부드러워서 강아지가 불편해하지 않아요. 좋습니다.', '2024-11-10T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('윤**', 1, 5, '명절 때 입히니까 온 가족이 좋아했어요. 재구매 의사 100%!', '2024-11-05T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('조**', 1, 5, '디테일이 살아있어요. 가격 대비 퀄리티가 훌륭합니다!', '2024-11-01T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('김**', 2, 5, '겨자색이 너무 예쁘고 후드 디자인이 귀여워요. 강추!', '2024-12-03T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('손**', 2, 5, '따뜻하고 세탁도 잘 돼요. 완전 만족합니다.', '2024-12-01T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('박**', 2, 5, '우리 강아지 겨울 옷으로 딱이에요. 품질 최고!', '2024-11-29T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('이**', 2, 4, '색상 예쁘고 좋은데 좀 더 두꺼우면 더 좋을 것 같아요.', '2024-11-27T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('최**', 2, 5, '산책 나갈 때 입히는데 사람들이 다 귀엽다고 해요 ㅎㅎ', '2024-11-25T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('정**', 2, 5, '캐주얼하면서도 세련된 느낌! 다른 색도 구매할게요.', '2024-11-22T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('강**', 2, 5, '강아지가 편해하네요. 입고 벗기도 쉬워서 좋아요.', '2024-11-20T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('윤**', 2, 5, '가격대비 품질 좋아요. 세탁 후에도 모양 그대로!', '2024-11-18T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('조**', 2, 4, '전체적으로 만족하지만 배송이 조금 늦었어요.', '2024-11-15T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('장**', 2, 5, '트렌디한 디자인! 주변에 추천하고 다녔어요.', '2024-11-12T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('김**', 3, 5, '당근 디자인 너무 귀여워요! 여름용으로 딱이겠어요.', '2024-11-30T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('박**', 3, 4, '가볍고 시원해 보여요. 날씨 따뜻해지면 자주 입힐 것 같아요.', '2024-11-28T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('이**', 3, 5, '알러지 있는 강아지인데 재질이 부드러워서 좋네요.', '2024-11-25T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('최**', 3, 4, '귀엽긴 한데 좀 더 저렴했으면 좋겠어요.', '2024-11-22T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('정**', 3, 5, '산뜻한 디자인! SNS 인증샷 찍기 좋아요.', '2024-11-20T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('김**', 4, 5, '비 오는 날 산책하기 완전 좋아요. 방수 기능 확실해요!', '2024-12-02T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('박**', 4, 5, '50% 할인해서 샀는데 가격 대비 너무 좋아요.', '2024-11-30T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('이**', 4, 4, '방수는 잘 되는데 사이즈 한 치수 크게 주문하세요.', '2024-11-28T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('최**', 4, 5, '곰돌이 디자인 너무 귀엽고 실용적이에요!', '2024-11-25T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('정**', 4, 5, '장마철에 필수템이에요. 배송도 빨라요.', '2024-11-23T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('강**', 4, 4, '물을 잘 튕기네요. 다만 좀 뻣뻣한 느낌은 있어요.', '2024-11-20T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('윤**', 4, 5, '비 맞아도 안쪽은 전혀 안 젖어요. 최고!', '2024-11-18T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('조**', 4, 5, '후드도 있어서 머리까지 보호돼요. 강추합니다.', '2024-11-15T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('장**', 4, 5, '우리 강아지 비 싫어하는데 이거 입히니까 괜찮아해요.', '2024-11-12T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('임**', 4, 4, '할인 가격이면 가성비 좋아요. 만족합니다.', '2024-11-10T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('김**', 5, 5, '색감이 정말 예쁘고 눈에 확 띄어요. 강아지 찾기 쉬워요 ㅎㅎ', '2024-12-01T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('박**', 5, 4, '디자인은 좋은데 세탁 시 색이 조금 빠지는 것 같아요.', '2024-11-29T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('이**', 5, 5, '귀여움 그 자체! 친구 강아지 옷으로 선물했어요.', '2024-11-27T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('최**', 5, 5, '개성있는 디자인 찾다가 이거 샀는데 대만족이에요.', '2024-11-24T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('정**', 5, 4, '좋긴 한데 가격이 조금 비싼 감이 있어요.', '2024-11-22T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('강**', 5, 5, '후드 부분이 너무 귀여워요. 재구매 의사 있어요!', '2024-11-19T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('윤**', 5, 4, '화려한 디자인 좋아하시면 추천드려요.', '2024-11-17T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('김**', 6, 4, '가볍고 따뜻해요. 할인해서 가성비 좋네요.', '2024-11-28T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('박**', 6, 4, '체크 패턴 클래식해서 좋아요.', '2024-11-25T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('이**', 6, 5, '겨울 필수템! 가격도 저렴하고 좋아요.', '2024-11-22T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('김**', 10, 5, '엄청 따뜻해요! 한파에도 끄떡없어요.', '2024-12-03T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('박**', 10, 5, '패딩이 두툼해서 겨울 나기 좋아요. 품질 최고!', '2024-12-01T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('이**', 10, 5, '가격은 좀 있지만 그만한 가치 있어요.', '2024-11-29T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('최**', 10, 4, '따뜻하긴 한데 좀 무거워요. 그래도 만족합니다.', '2024-11-27T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('정**', 10, 5, '디자인도 예쁘고 보온성도 좋아요. 강추!', '2024-11-25T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('강**', 10, 5, '겨울 외출 필수템이에요. 재구매 예정입니다.', '2024-11-23T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('윤**', 10, 5, '털도 안 빠지고 관리하기 편해요.', '2024-11-20T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('조**', 10, 4, '품질 좋은데 사이즈 체크 꼭 하세요!', '2024-11-18T00:00:00', NOW());
INSERT INTO reviews (user_id, product_id, rating, content, created_at, updated_at) VALUES ('장**', 10, 5, '프리미엄 느낌 나요. 돈 아깝지 않아요.', '2024-11-15T00:00:00', NOW());
